// @NAME@: iCEBreaker top with a PLL (template from fpga-box new ice40_pll_project). The PLL module `pll` is
// generated by icepll in the Makefile (FREQ_OUT MHz from the 12 MHz oscillator). Example: LED blinking from
// the PLL clock, green LED = PLL locked. Replace with your logic.
`default_nettype none
module top (input wire CLK, output wire LEDR_N, output wire LEDG_N);
    wire clk_pll, locked;
    pll u_pll (.clock_in(CLK), .clock_out(clk_pll), .locked(locked));
    reg [25:0] cnt = 0;
    always @(posedge clk_pll) cnt <= cnt + 1'b1;
    assign LEDR_N = ~cnt[25];
    assign LEDG_N = ~locked;
endmodule
